#include <map>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

// ---- minicsv: reads CSV text one record at a time. Do not change it. ----
namespace minicsv
{
    /// Reads comma-separated records from text.
    ///
    /// - Records end at '\n'; a '\r' just before it is ignored.
    /// - Blank lines produce no record; they are skipped.
    /// - Fields are separated by ','. A record ending in ',' has an empty last field.
    /// - A field that starts with '"' is quoted: it may contain ',', '\n' and
    ///   '""' (one double quote), and ends at the next lone '"', which must be
    ///   followed by ',' or the end of the record.
    class Reader
    {
    public:
        explicit Reader(std::string_view text) : text_{ text } {}

        /// Reads the next record into `fields`, replacing what it held.
        /// @return true if a record was read. false at the end of the text, or on
        ///         an error: then error() says which, and every later call also
        ///         returns false.
        bool next(std::vector<std::string>& fields)
        {
            fields.clear();
            if (!error_.empty()) return false;
            while (pos_ < text_.size())
            {
                if (text_[pos_] == '\n') { ++pos_; ++lineNow_; continue; }
                if (text_[pos_] == '\r' && (pos_ + 1 == text_.size() || text_[pos_ + 1] == '\n')) { ++pos_; continue; }
                break;
            }
            if (pos_ >= text_.size()) return false;
            line_ = lineNow_;
            for (;;)
            {
                std::string field;
                if (pos_ < text_.size() && text_[pos_] == '"')
                {
                    ++pos_;
                    for (;;)
                    {
                        if (pos_ >= text_.size()) { error_ = "unterminated quote"; return false; }
                        const char c{ text_[pos_++] };
                        if (c == '"')
                        {
                            if (pos_ < text_.size() && text_[pos_] == '"') { field += '"'; ++pos_; continue; }
                            break;
                        }
                        if (c == '\n') ++lineNow_;
                        field += c;
                    }
                    if (pos_ < text_.size() && text_[pos_] != ',' && text_[pos_] != '\n' && !endsWithCr())
                    {
                        error_ = "bad quote";
                        return false;
                    }
                }
                else
                {
                    while (pos_ < text_.size() && text_[pos_] != ',' && text_[pos_] != '\n') field += text_[pos_++];
                    if (!field.empty() && field.back() == '\r') field.pop_back();
                }
                fields.push_back(std::move(field));
                if (pos_ < text_.size() && text_[pos_] == ',') { ++pos_; continue; }
                if (endsWithCr()) ++pos_;
                if (pos_ < text_.size() && text_[pos_] == '\n') { ++pos_; ++lineNow_; }
                return true;
            }
        }

        /// The line number (from 1) on which the most recent record started,
        /// including a record that failed with an error.
        int line() const { return line_; }

        /// Empty while all is well. After next() fails: "unterminated quote" or "bad quote".
        const std::string& error() const { return error_; }

    private:
        bool endsWithCr() const { return pos_ < text_.size() && text_[pos_] == '\r' && (pos_ + 1 == text_.size() || text_[pos_ + 1] == '\n'); }

        std::string_view text_;
        std::size_t pos_{ 0 };
        int lineNow_{ 1 };
        int line_{ 0 };
        std::string error_;
    };
}

// ---- minitpl: fills in a text template. Do not change it. ----
namespace minitpl
{
    /// Renders `templ`, replacing each tag with a variable's value.
    ///
    /// A tag is {{ name }} or {{ name | filter }}; spaces inside the braces are
    /// optional. Names use letters, digits and '_'. Filters: upper, lower, trim.
    /// Text outside tags is copied unchanged.
    ///
    /// @return the rendered text, or std::nullopt on an error. Then, if `error`
    ///         is not null, *error is one of: "unclosed tag", "bad tag",
    ///         "unknown variable: NAME", "unknown filter: NAME".
    inline std::optional<std::string> render(std::string_view templ, const std::map<std::string, std::string>& vars, std::string* error = nullptr)
    {
        const auto fail{ [&](std::string message) -> std::optional<std::string> {
            if (error) *error = std::move(message);
            return std::nullopt;
        } };
        const auto trim{ [](std::string_view s) {
            while (!s.empty() && s.front() == ' ') s.remove_prefix(1);
            while (!s.empty() && s.back() == ' ') s.remove_suffix(1);
            return s;
        } };
        std::string out;
        std::size_t at{ 0 };
        for (;;)
        {
            const std::size_t open{ templ.find("{{", at) };
            if (open == std::string_view::npos) { out += templ.substr(at); return out; }
            out += templ.substr(at, open - at);
            const std::size_t close{ templ.find("}}", open + 2) };
            if (close == std::string_view::npos) return fail("unclosed tag");
            std::string_view inside{ trim(templ.substr(open + 2, close - open - 2)) };
            std::string_view filter;
            const std::size_t bar{ inside.find('|') };
            if (bar != std::string_view::npos)
            {
                filter = trim(inside.substr(bar + 1));
                inside = trim(inside.substr(0, bar));
            }
            if (inside.empty()) return fail("bad tag");
            for (char c : inside)
                if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return fail("bad tag");
            const auto it{ vars.find(std::string(inside)) };
            if (it == vars.end()) return fail("unknown variable: " + std::string(inside));
            std::string value{ it->second };
            if (bar != std::string_view::npos)
            {
                if (filter == "upper") { for (char& c : value) if (c >= 'a' && c <= 'z') c = static_cast<char>(c - 'a' + 'A'); }
                else if (filter == "lower") { for (char& c : value) if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a'); }
                else if (filter == "trim") value = std::string(trim(value));
                else return fail("unknown filter: " + std::string(filter));
            }
            out += value;
            at = close + 2;
        }
    }
}

