std::optional<std::string> report(std::string_view csv, std::string_view rowTemplate, std::string& error)
{
    minicsv::Reader reader{ csv };
    std::vector<std::string> header;
    if (!reader.next(header))
    {
        error = reader.error().empty() ? "no header" : "csv line " + std::to_string(reader.line()) + ": " + reader.error();
        return std::nullopt;
    }
    bool hasRowColumn{ false };
    for (const std::string& name : header) if (name == "row") hasRowColumn = true;

    std::string out;
    std::vector<std::string> fields;
    int row{ 0 };
    while (reader.next(fields))
    {
        ++row;
        if (fields.size() != header.size())
        {
            error = "csv line " + std::to_string(reader.line()) + ": expected " + std::to_string(header.size()) + " fields";
            return std::nullopt;
        }
        std::map<std::string, std::string> vars;
        for (std::size_t i{ 0 }; i < header.size(); ++i) vars[header[i]] = fields[i];
        if (!hasRowColumn) vars["row"] = std::to_string(row);
        std::string problem;
        const auto line{ minitpl::render(rowTemplate, vars, &problem) };
        if (!line)
        {
            error = "row " + std::to_string(row) + ": " + problem;
            return std::nullopt;
        }
        out += *line;
        out += '\n';
    }
    if (!reader.error().empty())
    {
        error = "csv line " + std::to_string(reader.line()) + ": " + reader.error();
        return std::nullopt;
    }
    error.clear();
    return out;
}

