std::string run(std::string_view csv, std::string_view templ) {
    std::string error{ "untouched" };
    const auto r{ report(csv, templ, error) };
    if (r) return r->empty() && !error.empty() ? "error not cleared" : *r;
    return "ERROR " + error;
}
TEST("a simple report") {
    CHECK_EQ(run("name,qty
rope,3
lamp,1
", "{{row}}. {{name}} x{{ qty }}"),
             std::string("1. rope x3
2. lamp x1
"));
    std::string error{ "x" };
    const auto r{ report("a
1
", "{{a}}", error) };
    CHECK(r.has_value() && error.empty());
}
TEST("quoted fields, blank lines and windows line endings") {
    CHECK_EQ(run("name,note

"Smith, J.","said ""hi"""

Lee,
", "{{name}}: {{note}}|"),
             std::string("Smith, J.: said "hi"|
Lee: |
"));
    CHECK_EQ(run("k,v
x,"two
lines"
y,z
", "{{k}}={{v}}"), std::string("x=two
lines
y=z
"));
}
TEST("filters and a column called row") {
    CHECK_EQ(run("row,item
A,box
B,bag
", "{{row}}:{{item|upper}}"), std::string("A:BOX
B:BAG
"));
    CHECK_EQ(run("item
  pad  
", "[{{ item | trim }}]"), std::string("[pad]
"));
}
TEST("headers without rows, and no header at all") {
    CHECK_EQ(run("a,b
", "{{a}}"), std::string(""));
    CHECK_EQ(run("", "{{a}}"), std::string("ERROR no header"));
    CHECK_EQ(run("


", "{{a}}"), std::string("ERROR no header"));
}
TEST("field counts") {
    CHECK_EQ(run("a,b
1,2
3
", "{{a}}"), std::string("ERROR csv line 3: expected 2 fields"));
    CHECK_EQ(run("a,b


1,2,3
", "{{a}}"), std::string("ERROR csv line 4: expected 2 fields"));
    CHECK_EQ(run("a,b
"x
y",2
1,2,
", "{{a}}"), std::string("ERROR csv line 4: expected 2 fields"));
}
TEST("errors from the CSV reader") {
    CHECK_EQ(run("a,b
1,2
"open,3
", "{{a}}"), std::string("ERROR csv line 3: unterminated quote"));
    CHECK_EQ(run("a
"x"y
", "{{a}}"), std::string("ERROR csv line 2: bad quote"));
    CHECK_EQ(run(""a
b", "{{a}}"), std::string("ERROR csv line 1: unterminated quote"));
}
