    CHECK_EQ(run("a
1
2
", "{{b}}"), std::string("ERROR row 1: unknown variable: b"));
    CHECK_EQ(run("a
1
", "{{a|shout}}"), std::string("ERROR row 1: unknown filter: shout"));
    CHECK_EQ(run("a
1
